using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);

// Register ProblemDetails services for RFC 7807 responses
builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = context =>
    {
        // Always include the trace identifier
        context.ProblemDetails.Extensions["traceId"] =
            context.HttpContext.TraceIdentifier;
    };
});

builder.Services.AddOpenApi();

var app = builder.Build();

// Global exception handler — maps known exceptions to Problem Details responses
app.UseExceptionHandler(exceptionApp =>
{
    exceptionApp.Run(async context =>
    {
        var exceptionFeature = context.Features.Get<IExceptionHandlerFeature>();
        var exception = exceptionFeature?.Error;

        var (statusCode, title) = exception switch
        {
            KeyNotFoundException   => (StatusCodes.Status404NotFound,    "Resource Not Found"),
            ArgumentException      => (StatusCodes.Status400BadRequest,  "Bad Request"),
            InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
            _ => (StatusCodes.Status500InternalServerError, "An unexpected error occurred")
        };

        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title  = title,
            // Only expose exception messages for client errors, never for 500s
            Detail = statusCode < 500 ? exception?.Message : null,
            Instance = context.Request.Path
        };
        problemDetails.Extensions["traceId"] = context.TraceIdentifier;

        context.Response.StatusCode = statusCode;
        await context.Response.WriteAsJsonAsync(problemDetails,
            context.RequestAborted);
    });
});

// Return Problem Details for non-exception error status codes (e.g. 404 from routing)
app.UseStatusCodePages();

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
}

app.UseHttpsRedirection();

// --- Demo endpoints to exercise each error path ---

app.MapGet("/items/{id:int}", (int id) =>
{
    if (id < 0)
        throw new ArgumentException($"ID must be non-negative, got {id}.");
    if (id == 0)
        throw new KeyNotFoundException($"Item with ID {id} was not found.");
    if (id == 999)
        throw new InvalidOperationException("Item 999 is in a conflicting state.");
    if (id == 500)
        throw new Exception("Something unexpected happened — this detail is hidden.");

    return Results.Ok(new { Id = id, Name = $"Item {id}" });
});

app.Run();

